message.content:
{
  "scenarios": [
    {
      "id": "M10-01",
      "category": "饮食偏好与个人生活习惯",
      "turns": [
        {
          "user": "我从小对花生过敏，每次接触都会起红疹。最近两年我开始尝试无麸质饮食，因为觉得这样身体更轻盈，但偶尔还是会偷吃面包。",
          "assistant": "已记录您的花生过敏史及近期无麸质饮食尝试情况。"
        },
        {
          "user": "补充一下，其实我对花生的反应在十岁那年最严重，后来虽然没完全好，但轻微接触没事了。另外，无麸质饮食我是从2023年春天正式开始的。",
          "assistant": "收到关于过敏严重程度变化及饮食开始时间的更正信息。"
        }
      ],
      "queries": [
        {
          "id": "q1",
          "query": "这位患者对哪种坚果有过敏反应？这种反应最早是在什么年龄段出现的？",
          "expected_facts": [
            "该患者对花生存在过敏反应。",
            "该患者在十岁时曾出现严重的过敏反应。"
          ],
          "required_groups": [
            ["花生", "花生类"],
            ["十岁", "10岁", "十岁那年"]
          ]
        },
        {
          "id": "q2",
          "query": "患者是从哪一年开始执行无麸质饮食计划的？目前是否完全坚持？",
          "expected_facts": [
            "该患者于2023年春天开始执行无麸质饮食计划。",
            "该患者目前偶尔仍会食用含麸质食物如面包。"
          ],
          "required_groups": [
            ["2023年", "2023年春天"],
            ["偶尔偷吃", "不完全坚持", "偶尔食用"]
          ]
        }
      ]
    },
    {
      "id": "M10-02",
      "category": "饮食偏好与个人生活习惯",
      "turns": [
        {
          "user": "我是个素食主义者，已经坚持了五年不吃任何肉类。不过我对海鲜没有抵触，偶尔会吃鱼，但不吃贝类，因为小时候被贝壳划伤过。",
          "assistant": "已确认您的素食习惯及海鲜摄入的具体限制情况。"
        },
        {
          "user": "更正一下，我其实是半素食者，只吃鱼肉和鸡蛋，其他肉类都不碰。那个贝壳划伤是八年前的事，导致我现在看到贝类就恶心。",
          "assistant": "已更新您的饮食分类为半素食并记录了贝类回避的心理原因。"
        }
      ],
      "queries": [
        {
          "id": "q1",
          "query": "该患者的具体饮食类型是什么？除了鱼类外还摄入哪些动物性食品？",
          "expected_facts": [
            "该患者属于半素食者，仅摄入鱼肉和鸡蛋。",
            "该患者不食用除鱼肉以外的其他肉类。"
          ],
          "required_groups": [
            ["半素食", "半素食者"],
            ["鱼肉", "鱼", "鸡蛋"]
          ]
        },
        {
          "id": "q2",
          "query": "患者为何回避贝类？这一心理阴影源于多久之前的事件？",
          "expected_facts": [
            "该患者因八年前被贝壳划伤而回避贝类。",
            "该患者看到贝类会产生恶心感。"
          ],
          "required_groups": [
            ["八年前", "8年前"],
            ["被贝壳划伤", "贝壳划伤", "划伤事件"]
          ]
        }
      ]
    },
    {
      "id": "M10-03",
      "category": "饮食偏好与个人生活习惯",
      "turns": [
        {
          "user": "我有喝咖啡的习惯，每天早晨必须喝一杯黑咖啡才能清醒。但我对咖啡因很敏感，下午三点后喝就会失眠，所以严格控制在上午饮用。",
          "assistant": "已记录您的咖啡饮用时间及对咖啡因的敏感度。"
        },
        {
          "user": "补充说明，我其实是从三年前才开始养成这个习惯的，之前并不怎么喝咖啡。而且如果不小心喝了加糖的咖啡，我会感到胃部不适。",
          "assistant": "已补充咖啡习惯的起始时间及对加糖咖啡的反应。"
        }
      ],
      "queries": [
        {
          "id": "q1",
          "query": "患者每日饮用咖啡的时间段有何限制？若违反此限制会出现什么后果？",
          "expected_facts": [
            "该患者仅在上午饮用咖啡，下午三点后不喝。",
            "该患者若在下午三点后饮用咖啡会导致失眠。"
          ],
          "required_groups": [
            ["上午", "早上"],
            ["下午三点后", "午后", "失眠"]
          ]
        },
        {
          "id": "q2",
          "query": "患者何时开始形成每日饮咖的习惯？饮用何种配方的咖啡会引起身体不适？",
          "expected_facts": [
            "该患者从三年前开始养成每日饮咖习惯。",
            "该患者饮用加糖咖啡时会感到胃部不适。"
          ],
          "required_groups": [
            ["三年前", "3年前"],
            ["加糖咖啡", "含糖咖啡", "胃部不适"]
          ]
        }
      ]
    },
    {
      "id": "M10-04",
      "category": "饮食偏好与个人生活习惯",
      "turns": [
        {
          "user": "我不吃辣，一点辣椒都受不了，一吃喉咙就痛。所以我点菜时总是特意要求免辣，哪怕是最微辣的汤底也不行。",
          "assistant": "已记录您对辛辣食物的不耐受情况及点餐习惯。"
        },
        {
          "user": "其实以前我能吃一点点辣，大概是五年前突然变得完全不能吃辣了，现在连闻着味道都觉得嗓子不舒服。",
          "assistant": "已更新您辣味耐受度变化的时间点及当前症状描述。"
        }
      ],
      "queries": [
        {
          "id": "q1",
          "query": "患者目前对辣味的耐受程度如何？进食或接触辣味后有何生理反应？",
          "expected_facts": [
            "该患者目前完全无法耐受任何辣味。",
            "该患者接触辣味后会出现喉咙疼痛或不适。"
          ],
          "required_groups": [
            ["完全不能", "一点都不能", "完全无法"],
            ["喉咙痛", "嗓子不舒服", "喉咙不适"]
          ]
        },
        {
          "id": "q2",
          "query": "患者失去辣味耐受能力发生在什么时候？此前是否有过能吃辣的经历？",
          "expected_facts": [
            "该患者在五年前突然失去了对辣味的耐受能力。",
            "该患者五年前之前能够少量食用辣味食物。"
          ],
          "required_groups": [
            ["五年前", "5年前"],
            ["以前能吃", "曾经能", "过去能"]
          ]
        }
      ]
    },
    {
      "id": "M10-05",
      "category": "饮食偏好与个人生活习惯",
      "turns": [
        {
          "user": "我习惯晚上十点前吃完晚餐，之后不再进食固体食物。这是为了保持体重，也避免睡前胃胀，已经坚持了十年。",
          "assistant": "已记录您的晚餐截止时间及长期饮食习惯。"
        },
        {
          "user": "更正一下，其实我是从七年前开始严格执行这个规则的，之前只是偶尔这样做。而且如果不得不晚吃，我会选择喝点温牛奶而不是吃东西。",
          "assistant": "已修正晚餐时间规则的执行起始时间及替代方案。"
        }
      ],
      "queries": [
        {
          "id": "q1",
          "query": "患者设定的晚餐结束时间是什么时候？这一习惯持续了多久？",
          "expected_facts": [
            "该患者习惯在晚上十点前结束晚餐。",
            "该患者严格执行此规则已有七年时间。"
          ],
          "required_groups": [
            ["晚上十点", "22点", "十点前"],
            ["七年", "7年", "七年前开始"]
          ]
        },
        {
          "id": "q2",
          "query": "若患者被迫在晚餐时间后进食，通常会选择什么替代品？",
          "expected_facts": [
            "该患者在晚餐后若需进食会选择喝温牛奶。",
            "该患者晚餐后避免食用固体食物。"
          ],
          "required_groups": [
            ["温牛奶", "热牛奶", "牛奶"],
            ["固体食物", "吃东西", "固体"]
          ]
        }
      ]
    },
    {
      "id": "M10-06",
      "category": "饮食偏好与个人生活习惯",
      "turns": [
        {
          "user": "我对乳制品非常敏感，喝牛奶后会拉肚子，所以家里从来不买牛奶。但我可以接受酸奶和奶酪，因为它们经过发酵处理。",
          "assistant": "已记录您对液态奶的不耐受及对发酵乳制品的接受情况。"
        },
        {
          "user": "补充一下，这种乳糖不耐受是遗传的，从我记事起就这样了。不过最近我发现有些品牌的酸奶也会让我轻微腹胀，正在尝试筛选。",
          "assistant": "已补充乳糖不耐受的成因及近期对部分酸奶的反应。"
        }
      ],
      "queries": [
        {
          "id": "q1",
          "query": "患者对哪类乳制品存在明确的不耐受反应？其根本原因是什么？",
          "expected_facts": [
            "该患者饮用牛奶后会出现腹泻症状。",
            "该患者的乳糖不耐受具有遗传背景。"
          ],
          "required_groups": [
            ["牛奶", "液态奶"],
            ["遗传", "天生", "遗传性"]
          ]
        },
        {
          "id": "q2",
          "query": "患者目前能否食用所有类型的发酵乳制品？是否存在例外情况？",
          "expected_facts": [
            "该患者通常可食用酸奶和奶酪等发酵乳制品。",
            "该患者近期发现部分品牌酸奶会导致轻微腹胀。"
          ],
          "required_groups": [
            ["酸奶", "奶酪", "发酵乳制品"],
            ["轻微腹胀", "腹胀", "不适"]
          ]
        }
      ]
    },
    {
      "id": "M10-07",
      "category": "饮食偏好与个人生活习惯",
      "turns": [
        {
          "user": "我特别喜欢吃甜食，尤其是巧克力，每天都要吃一块黑巧。但自从去年体检血糖偏高后，我就把频率降到了每周两次。",
          "assistant": "已记录您的甜食偏好及基于健康检查后的调整行为。"
        },
        {
          "user": "更正一下，不是去年，而是两年前体检发现的血糖问题。现在我只在周末吃，而且严格控制在一小块以内，平时完全不吃。",
          "assistant": "已修正血糖异常发现时间及目前的甜食摄入频率。"
        }
      ],
      "queries": [
        {
          "id": "q1",
          "query": "患者因何健康指标异常而调整了甜食摄入频率？该指标异常是何时发现的？",
          "expected_facts": [
            "该患者因血糖偏高而减少了甜食摄入。",
            "该患者的血糖异常是在两年前体检中发现的。"
          ],
          "required_groups": [
            ["血糖偏高", "血糖高", "血糖异常"],
            ["两年前", "2年前"]
          ]
        },
        {
          "id": "q2",
          "query": "患者目前食用巧克力的具体频率和份量控制是怎样的？",
          "expected_facts": [
            "该患者目前仅在周末食用巧克力。",
            "该患者每次食用量严格控制在一小块以内。"
          ],
          "required_groups": [
            ["周末", "周六日"],
            ["一小块", "少量", "严格控制"]
          ]
        }
      ]
    },
    {
      "id": "M10-08",
      "category": "饮食偏好与个人生活习惯",
      "turns": [
        {
          "user": "我有嚼口香糖的习惯，几乎整天都在嚼，主要是薄荷味的。这帮助我集中注意力，但有时候嚼太久下巴会酸痛。",
          "assistant": "已记录您的口香糖咀嚼习惯及其带来的副作用。"
        },
        {
          "user": "补充说，我从大学时期就开始有这个习惯了，大概有八年了。最近换了无糖口香糖，感觉下巴酸痛的情况稍微好了一点。",
          "assistant": "已补充习惯持续时间及更换产品后的改善情况。"
        }
      ],
      "queries": [
        {
          "id": "q1",
          "query": "患者维持嚼口香糖习惯的大致时长是多少？最初是为了什么目的？",
          "expected_facts": [
            "该患者嚼口香糖的习惯已持续约八年。",
            "该患者嚼口香糖是为了帮助集中注意力。"
          ],
          "required_groups": [
            ["八年", "8年", "大学时期至今"],
            ["集中注意力", "专注", "提神"]
          ]
        },
        {
          "id": "q2",
          "query": "患者长期使用口香糖导致了什么身体反应？近期采取了什么措施缓解？",
          "expected_facts": [
            "该患者长期嚼口香糖会导致下巴酸痛。",
            "该患者改用无糖口香糖后症状有所缓解。"
          ],
          "required_groups": [
            ["下巴酸痛", "颚部疼痛", "酸痛"],
            ["无糖口香糖", "换用无糖", "缓解"]
          ]
        }
      ]
    },
    {
      "id": "M10-09",
      "category": "饮食偏好与个人生活习惯",
      "turns": [
        {
          "user": "我不喝酒，滴酒不沾，因为父亲酗酒对我影响很大。所以我不仅自己不喝，家里也不存放任何酒精饮料。",
          "assistant": "已记录您拒绝饮酒的个人原因及家庭环境设置。"
        },
        {
          "user": "更正一下，其实我在二十多岁时尝试过喝啤酒，但一次醉酒后呕吐得很厉害，从那以后就彻底戒掉了，到现在已经十年没碰过酒。",
          "assistant": "已更新您戒酒的具体契机及禁酒时长。"
        }
      ],
      "queries": [
        {
          "id": "q1",
          "query": "患者彻底戒酒的决定是基于什么具体经历做出的？",
          "expected_facts": [
            "该患者因一次醉酒呕吐严重而决定戒酒。",
            "该患者在二十多岁时有过饮酒尝试。"
          ],
          "required_groups": [
            ["醉酒呕吐", "吐得很厉害", "呕吐"],
            ["二十多岁", "20多岁"]
          ]
        },
        {
          "id": "q2",
          "query": "患者目前禁酒的状态持续了多长时间？家庭环境中是否允许存放酒类？",
          "expected_facts": [
            "该患者已持续十年未饮酒。",
            "该患者家中不存放任何酒精饮料。"
          ],
          "required_groups": [
            ["十年", "10年"],
            ["不存放", "家里没有", "禁止存放"]
          ]
        }
      ]
    },
    {
      "id": "M10-10",
      "category": "饮食偏好与个人生活习惯",
      "turns": [
        {
          "user": "我习惯早餐吃燕麦粥，加了蓝莓和坚果。这个习惯是我母亲教我的，她认为这样营养均衡，我已经吃了十几年了。",
          "assistant": "已记录您的早餐食谱构成及习惯来源。"
        },
        {
          "user": "补充一下，其实我是在搬去独居后才开始自己煮燕麦粥的，大概六年前。之前住家时是母亲做给我吃的，那时我还经常加蜂蜜。",
          "assistant": "已补充独立烹饪该早餐的时间节点及过往配料差异。"
        }
      ],
      "queries": [
        {
          "id": "q1",
          "query": "患者目前早餐燕麦粥中固定的配料有哪些？这一饮食习惯源自何处？",
          "expected_facts": [
            "该患者早餐燕麦粥固定搭配蓝莓和坚果。",
            "该患者的早餐习惯源自母亲的教导。"
          ],
          "required_groups": [
            ["蓝莓", "坚果", "燕麦粥"],
            ["母亲", "妈妈", "家人教导"]
          ]
        },
        {
          "id": "q2",
          "query": "患者从何时开始独立制作这份早餐？过去由他人制作时添加了什么额外成分？",
          "expected_facts": [
            "该患者从六年前搬去独居后开始独立制作燕麦粥。",
            "该患者过去食用时经常添加蜂蜜。"
          ],
          "required_groups": [
            ["六年前", "6年前", "独居后"],
            ["蜂蜜", "加蜜"]
          ]
        }
      ]
    }
  ]
}
